import re

with open('/tmp/decisions_yaml.txt', 'r') as f:
    lines = f.readlines()

# Search patterns
patterns = [
    re.compile(r'ScienceWorld', re.IGNORECASE),
    re.compile(r'science_world', re.IGNORECASE),
    re.compile(r'sw_'),
    re.compile(r'Cell A(?![a-zA-Z-])|Cell C(?![a-zA-Z-])'),
]

# Find all line numbers that match
matching_lines = set()
for i, line in enumerate(lines):
    for p in patterns:
        if p.search(line):
            matching_lines.add(i)

# Find decision block boundaries (lines starting with "- id: D")
decision_starts = []
for i, line in enumerate(lines):
    if re.match(r'^- id: D\d+', line):
        decision_starts.append(i)

# Also find the header line
header_end = 0
for i, line in enumerate(lines):
    if line.strip().startswith('decisions:'):
        header_end = i + 1
        break

# For each matching line, find which decision block it belongs to
matching_decisions = set()
for ml in matching_lines:
    # Find the decision start that is <= ml
    best = None
    for ds in decision_starts:
        if ds <= ml:
            best = ds
        else:
            break
    if best is not None:
        matching_decisions.add(best)

# Extract each matching decision block
print(f"Found {len(matching_decisions)} decision blocks containing ScienceWorld-related content\n")
print("=" * 80)

for ds in sorted(matching_decisions):
    # Find the end of this block (next decision start or EOF)
    end = len(lines)
    for next_ds in decision_starts:
        if next_ds > ds:
            end = next_ds
            break

    block = ''.join(lines[ds:end])
    print(f"\n[Lines {ds+1}-{end}]")
    print(block)
    print("=" * 80)

